// ClaimAllowance returns the current token-bucket allowance (remaining coins
// that can be claimed right now) for each rarity 0–6, for the given address.
// The result is a JSON object: {"r0":1234,"r1":56,...,"r6":42}.
// The client should call this before constructing a ClaimMine/ClaimAndMint
// payload to avoid over-claiming and wasting gas on a panicking tx.
func ClaimAllowance(playerAddr string) string {
	tool := bestOwnedTool(playerAddr)
	rates, hasRates := claimRatePerMin[tool]
	if !hasRates {
		rates = claimRatePerMin["hands"]
	}

	now := time.Now().Unix()
	var parts []string

	for r := 0; r < 7; r++ {
		baseRate := rates[r]
		var effectiveRate uint64
		if r == 0 {
			effectiveRate = (baseRate * skillDmgHeadroom * skillDustHeadroom) / 10000
		} else {
			effectiveRate = (baseRate * skillDmgHeadroom) / 100
		}
		if effectiveRate == 0 {
			effectiveRate = baseRate
		}

		// Milli-unit cap and refill — mirrors enforceClaimRate exactly.
		capMillis := effectiveRate * uint64(claimBucketSecs) * 1000 / 60

		bucketKey := playerAddr + ":" + strconv.Itoa(r)
		storedMillis := capMillis // default: full cap
		lastTs := now
		if claimBuckets.Has(bucketKey) {
			state := claimBuckets.Get(bucketKey).(string)
			p := strings.SplitN(state, ":", 2)
			if len(p) == 2 {
				storedMillis, _ = strconv.ParseUint(p[0], 10, 64)
				lastTs, _ = strconv.ParseInt(p[1], 10, 64)
			}
		}

		elapsed := now - lastTs
		if elapsed > 0 {
			refilledMillis := uint64(elapsed) * effectiveRate * 1000 / 60
			storedMillis += refilledMillis
			if storedMillis > capMillis {
				storedMillis = capMillis
			}
		}

		// Return whole-coin floor
		accrued := storedMillis / 1000
		parts = append(parts, `"r`+strconv.Itoa(r)+`":`+strconv.FormatUint(accrued, 10))
	}
	return "{" + strings.Join(parts, ",") + "}"
}

